const CLIENT_SAFETY_CSS=`
.trial-card{display:grid;gap:12px;margin-bottom:14px;padding:16px;border-radius:14px;background:linear-gradient(135deg,rgba(8,145,178,.12),rgba(124,58,237,.1));border:1px solid rgba(103,232,249,.2)}.trial-card>div:first-child{display:flex;align-items:center;gap:8px;flex-wrap:wrap}.trial-card h3{margin:0;color:#fecdd3;font-size:.88rem}.trial-card.expired{background:rgba(127,29,29,.09);border-color:rgba(251,113,133,.22)}.founder-badge{padding:4px 8px;border-radius:999px;background:rgba(245,158,11,.1);border:1px solid rgba(245,158,11,.22);color:#fde68a;font-size:.62rem}.trial-limits{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.trial-limits .info{padding:9px;border-radius:9px;background:rgba(2,6,23,.28);border:1px solid rgba(148,163,184,.08)}.founder-copy{display:grid;gap:4px;color:#c4b5fd;font-size:.7rem}.founder-copy b{color:#fef3c7}.trial-actions{display:flex;gap:8px;flex-wrap:wrap}
.lifecycle-filter{display:flex;gap:6px;flex-wrap:wrap;margin:0 0 12px}.lifecycle-filter button{padding:7px 10px;border-radius:999px;border:1px solid rgba(148,163,184,.12);background:rgba(15,23,42,.55);color:#94a3b8;font-size:.66rem;cursor:pointer}.lifecycle-filter button.active{border-color:rgba(34,211,238,.42);background:rgba(34,211,238,.09);color:#a5f3fc}.lifecycle-filter small{margin-left:5px;color:#64748b}.client-card.archived{opacity:.76;border-color:rgba(148,163,184,.16)}.restore{border-color:rgba(34,211,238,.25);color:#a5f3fc}.danger-zone{margin-top:16px;padding:14px;border-radius:12px;border:1px solid rgba(251,113,133,.2);background:rgba(127,29,29,.08)}.danger-zone>div:first-child{margin-bottom:10px}.danger-zone h3{margin:0 0 5px;color:#fecdd3;font-size:.78rem}.danger-zone p{margin:0;color:#94a3b8;font-size:.67rem;line-height:1.55}.danger-actions,.confirm-actions{display:flex;gap:7px;flex-wrap:wrap}.danger-button{padding:8px 11px;border-radius:8px;border:1px solid rgba(251,113,133,.32);background:rgba(225,29,72,.1);color:#fda4af;font-size:.68rem;font-weight:700;cursor:pointer}.danger-button:hover{background:rgba(225,29,72,.18);border-color:rgba(251,113,133,.55)}.delete-confirm{margin-top:12px;padding:13px;border-radius:10px;background:rgba(2,6,23,.55);border:1px solid rgba(251,113,133,.18)}.delete-warning{margin:10px 0;padding:9px;border-radius:8px;background:rgba(245,158,11,.08);border:1px solid rgba(245,158,11,.18);color:#fde68a;font-size:.66rem;line-height:1.5}.confirm-actions{margin-top:11px}@media(max-width:600px){.danger-actions,.confirm-actions{display:grid;grid-template-columns:1fr}.danger-actions button,.confirm-actions button{width:100%}}
`;
